float vrchHandWindowCross(vec2 a, vec2 b) {
  return a.x * b.y - a.y * b.x;
}
vec4 vrchHandWindowLandmark(float pointIndex, float rowCenter) {
  return vrchSampleSignalTexture(1, vec2((pointIndex + 0.5) / 32.0, rowCenter));
}
float vrchHandWindowEdgeDistance(vec2 point, vec2 startPoint, vec2 endPoint) {
  vec2 edge = endPoint - startPoint;
  return vrchHandWindowCross(edge, point - startPoint) / max(length(edge), 0.0001);
}
vec4 vrchHandWindowGlass(vec2 uv, float effect) {
  vec2 resolution = max(iResolution.xy, vec2(1.0));
  vec2 pixel = vec2(1.0) / resolution;
  float phase = iTime * 0.268;
  vec2 surface = vec2(
    sin(uv.y * 17.0 + phase) + cos((uv.x + uv.y) * 11.0 - phase * 0.7),
    cos(uv.x * 15.0 - phase * 0.8) + sin((uv.x - uv.y) * 13.0 + phase)
  ) * 0.5;
  vec2 refractedUv = clamp(uv + surface * pixel * effect * 7.0, vec2(0.0), vec2(1.0));
  vec4 centerSample = vrchSampleSource1(refractedUv);
  vec3 glass = centerSample.rgb;
  vec2 spread = pixel * (1.0 + effect * 5.0);

  if (effect >= 0.12) {
    vec3 sampleMinus = vrchSampleSource1(clamp(refractedUv - spread, vec2(0.0), vec2(1.0))).rgb;
    vec3 samplePlus = vrchSampleSource1(clamp(refractedUv + spread, vec2(0.0), vec2(1.0))).rgb;
    vec3 dispersed = vec3(samplePlus.r, centerSample.g, sampleMinus.b);
    float threeSampleMix = smoothstep(0.12, 0.30, effect);
    glass = mix(glass, dispersed, threeSampleMix * (0.08 + effect * 0.18));

    if (effect >= 0.45) {
      vec2 perpendicular = vec2(-spread.y, spread.x);
      vec3 sampleLeft = vrchSampleSource1(clamp(refractedUv - perpendicular, vec2(0.0), vec2(1.0))).rgb;
      vec3 sampleRight = vrchSampleSource1(clamp(refractedUv + perpendicular, vec2(0.0), vec2(1.0))).rgb;
      vec3 frostFive = (centerSample.rgb + sampleMinus + samplePlus + sampleLeft + sampleRight) * 0.2;
      float fiveSampleMix = smoothstep(0.45, 0.62, effect);
      glass = mix(glass, frostFive, fiveSampleMix * effect * 0.22);

      if (effect >= 0.78) {
        vec2 diagonal = vec2(spread.x, -spread.y) * 1.45;
        vec3 sampleDiagonalA = vrchSampleSource1(clamp(refractedUv - diagonal, vec2(0.0), vec2(1.0))).rgb;
        vec3 sampleDiagonalB = vrchSampleSource1(clamp(refractedUv + diagonal, vec2(0.0), vec2(1.0))).rgb;
        vec3 frostSeven = (frostFive * 5.0 + sampleDiagonalA + sampleDiagonalB) * 0.142857;
        float sevenSampleMix = smoothstep(0.78, 0.92, effect);
        glass = mix(glass, frostSeven, sevenSampleMix * effect * 0.28);
      }
    }
  }
  return vec4(glass, centerSample.a);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / max(iResolution.xy, vec2(1.0));
  vec4 sourceA = vrchSampleSource0(uv);

  vec4 leftThumb = vrchHandWindowLandmark(4.0, 0.25);
  vec4 leftIndex = vrchHandWindowLandmark(8.0, 0.25);
  vec4 rightThumb = vrchHandWindowLandmark(4.0, 0.75);
  vec4 rightIndex = vrchHandWindowLandmark(8.0, 0.75);
  float pointConfidence = min(min(leftThumb.a, leftIndex.a), min(rightThumb.a, rightIndex.a));
  float trackingReady = step(0.001, pointConfidence) * step(0.001, vrchReadSignal(0));

  vec2 center = (leftThumb.xy + leftIndex.xy + rightThumb.xy + rightIndex.xy) * 0.25;
  vec2 p0 = center + (leftThumb.xy - center) * uParam_window_size;
  vec2 p1 = center + (leftIndex.xy - center) * uParam_window_size;
  vec2 p2 = center + (rightThumb.xy - center) * uParam_window_size;
  vec2 p3 = center + (rightIndex.xy - center) * uParam_window_size;
  float a0 = atan(p0.y - center.y, p0.x - center.x);
  float a1 = atan(p1.y - center.y, p1.x - center.x);
  float a2 = atan(p2.y - center.y, p2.x - center.x);
  float a3 = atan(p3.y - center.y, p3.x - center.x);
  if (a0 > a1) { float ta = a0; a0 = a1; a1 = ta; vec2 tp = p0; p0 = p1; p1 = tp; }
  if (a2 > a3) { float ta = a2; a2 = a3; a3 = ta; vec2 tp = p2; p2 = p3; p3 = tp; }
  if (a0 > a2) { float ta = a0; a0 = a2; a2 = ta; vec2 tp = p0; p0 = p2; p2 = tp; }
  if (a1 > a3) { float ta = a1; a1 = a3; a3 = ta; vec2 tp = p1; p1 = p3; p3 = tp; }
  if (a1 > a2) { float ta = a1; a1 = a2; a2 = ta; vec2 tp = p1; p1 = p2; p2 = tp; }

  float twiceArea = vrchHandWindowCross(p0, p1) + vrchHandWindowCross(p1, p2) + vrchHandWindowCross(p2, p3) + vrchHandWindowCross(p3, p0);
  float orientation = twiceArea < 0.0 ? -1.0 : 1.0;
  float edgeDistance = min(min(vrchHandWindowEdgeDistance(uv, p0, p1), vrchHandWindowEdgeDistance(uv, p1, p2)), min(vrchHandWindowEdgeDistance(uv, p2, p3), vrchHandWindowEdgeDistance(uv, p3, p0))) * orientation;
  float shapeReady = step(0.001, abs(twiceArea));
  float softness = max(0.0005, uParam_softness);
  float windowMask = smoothstep(-softness, softness, edgeDistance);
  if (uParam_invert) windowMask = 1.0 - windowMask;
  windowMask *= trackingReady * shapeReady;
  float revealMask = clamp(windowMask * uParam_reveal, 0.0, 1.0);
  float glassEffect = clamp(uParam_glass_effect, 0.0, 1.0);
  vec4 sourceB = sourceA;
  vec3 color = sourceA.rgb;
  if (revealMask > 0.0001) {
    sourceB = vrchHandWindowGlass(uv, glassEffect);
    vec3 windowColor = sourceB.rgb;
    if (uParam_invert_color) windowColor = vec3(1.0) - windowColor;
    float colorMix = clamp(uParam_color_mix, 0.0, 1.0);
    windowColor = mix(windowColor, windowColor * uParam_window_color.rgb, colorMix);
    float transmittedLight = dot(windowColor, vec3(0.2126, 0.7152, 0.0722));
    windowColor += uParam_window_color.rgb * transmittedLight * colorMix * (0.035 + glassEffect * 0.055);
    float innerHighlight = (1.0 - smoothstep(0.0, max(softness * 4.0, 0.006), abs(edgeDistance))) * trackingReady * shapeReady;
    windowColor += mix(vec3(1.0), uParam_window_color.rgb, 0.55) * innerHighlight * (0.035 + glassEffect * 0.10) * clamp(0.012 / softness, 0.25, 4.0);
    float shimmer = 0.5 + 0.5 * sin(iTime * 11.6 + uv.x * 42.0 - uv.y * 29.0);
    windowColor += mix(vec3(1.0), uParam_window_color.rgb, 0.35) * shimmer * glassEffect * 0.035;
    color = mix(sourceA.rgb, clamp(windowColor, 0.0, 1.0), revealMask);
  }
  vec4 tracking = vrchSampleSignalTexture(0, uv);
  float skeleton = max(smoothstep(0.02, 0.88, tracking.r), smoothstep(0.02, 0.88, tracking.g));
  float debugOpacity = uParam_show_skeleton ? skeleton * step(0.001, vrchReadSignal(0)) : 0.0;
  color = mix(color, vec3(0.12, 0.95, 1.0), clamp(debugOpacity * 0.9, 0.0, 1.0));
  fragColor = vec4(color, mix(sourceA.a, sourceB.a, revealMask));
}
